  .demo-container {
    width: 100%;
    max-width: 400px;
    height: 300px;
    margin: 24px auto;
    background-color: rgba(128, 128, 128, 0.1);
    border: 1px solid rgba(128, 128, 128, 0.2);
    border-radius: 4px;
    / 使用 Flex 布局实现子元素水平和垂直居中 /
    display: flex;
    align-items: center;
    justify-content: center;
  }

